import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import TabNav, { TabKey, TABS } from './components/TabNav';
import Accueil from './pages/Accueil';
import Apropos from './pages/Apropos';
import Realisations from './pages/Realisations';
import Contact from './pages/Contact';

// Безопасный доступ к window для SSR
const hasWindow = typeof window !== 'undefined';

const DEFAULT_TAB: TabKey = 'accueil';
const VALID_KEYS = new Set< TabKey >(TABS.map(t => t.key));

function readHash(): TabKey {
  if (!hasWindow) return DEFAULT_TAB;
  const h = (window.location.hash.replace('#', '') || DEFAULT_TAB) as TabKey;
  return (VALID_KEYS.has(h) ? h : DEFAULT_TAB);
}

function writeHash(t: TabKey, replace = false) {
  if (!hasWindow) return;
  const next = `#${t}`;
  if (replace) {
    history.replaceState(null, '', next);
  } else {
    history.pushState({ tab: t }, '', next);
  }
}

function useHashTab() {
  const [tab, setTab] = useState<TabKey>(() => readHash());

  // Слушаем изменения истории/хэша (back/forward, внешнее изменение)
  useEffect(() => {
    if (!hasWindow) return;
    const handler = () => {
      const h = readHash();
      setTab(prev => (prev !== h ? h : prev));
    };
    window.addEventListener('popstate', handler);
    window.addEventListener('hashchange', handler);
    return () => {
      window.removeEventListener('popstate', handler);
      window.removeEventListener('hashchange', handler);
    };
  }, []);

  const navigate = useCallback((t: TabKey) => {
    setTab(curr => {
      if (curr !== t) writeHash(t);
      return t;
    });
  }, []);

  return { tab, navigate };
}

export default function App() {
  const { tab, navigate } = useHashTab();
  const sectionRef = useRef<HTMLElement>(null);

  // Сброс скролла панели при смене вкладки c учетом prefers-reduced-motion
  useEffect(() => {
    const el = sectionRef.current;
    if (!el) return;
    const prefersReduced =
      hasWindow &&
      window.matchMedia &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    el.scrollTo({ top: 0, behavior: prefersReduced ? 'auto' : 'smooth' });
  }, [tab]);

  const Page = useMemo(() => {
    switch (tab) {
      case 'accueil':      return <Accueil      goTo={navigate} />;
      case 'apropos':      return <Apropos />;
      case 'realisations': return <Realisations />;
      case 'contact':      return <Contact />;
      default:             return <Accueil      goTo={navigate} />;
    }
  }, [tab, navigate]);

  // Поддержка прямых ссылок: если хэш пустой при первом рендере, проставим дефолт (replace, чтобы не мусорить историю)
  useEffect(() => {
    if (hasWindow && !window.location.hash) writeHash(DEFAULT_TAB, true);
  }, []);

  // Генерируем доступные панели с правильными aria-ссылками
  const panelIdBase = 'main';

  return (
    <div className="app">
      <a className="skip-link" href="#content">Aller au contenu</a>

      <header className="header" role="banner">
        <div className="container nav" role="navigation" aria-label="Navigation principale">
          <div className="brand">
            <div className="logo" aria-hidden="true" aria-label="+Propre">+</div>
            <span className="brand-name">+Propre</span>
            <span className="badge" title="Couverture Île-de-France">
              Service de nettoyage & d’entretien
            </span>
          </div>

          <TabNav active={tab} onChange={navigate} idBase={panelIdBase} />

          <div className="quick-info">
            <a href="tel:+33765551111">📞 07&nbsp;65&nbsp;55&nbsp;11&nbsp;11</a>
            <span aria-hidden="true">•</span>
            <a href="mailto:contact@plus-propre.fr">✉️ contact@plus-propre.fr</a>
          </div>
        </div>
      </header>

      <main id="content" className="container main" ref={sectionRef} role="main" aria-live="polite">
        {/* Панели вкладок — одна активная, остальные скрыты семантически */}
        {TABS.map(({ key }) => {
          const selected = tab === key;
          return (
            <section
              key={key}
              role="tabpanel"
              id={`${panelIdBase}-panel-${key}`}
              aria-labelledby={`${panelIdBase}-tab-${key}`}
              hidden={!selected}
            >
              {selected && Page /* монтируем только активную страницу */}
            </section>
          );
        })}

        <footer className="footer">
          <div>© {new Date().getFullYear()} +Propre — Tous droits réservés.</div>
          <div className="small">
            Mentions légales — Produits écoresponsables — Assurés &amp; formés.
          </div>
        </footer>
      </main>
    </div>
  );
}
